// Real UART pins, CRC and top-level commands. Stimuli generated by host tests.
`timescale 1ns/1ps
module tb_debug_uart;
    reg clk=0,rst_n=0,rx=1,control_tick=0;
    always #10 clk=~clk;
    wire tx;
    j280_top dut(.clk_50m(clk),.rst_n(rst_n),.key_sw(4'hf),.dip_sw(2'b00),
        .uart_rx(rx),.uart_tx(tx),.adc_data_in(10'd781),.adc_otr(1'b0),
        .enc1_a(1'b0),.enc1_b(1'b0),.enc2_a(1'b0),.enc2_b(1'b0));
    // Accelerate UART/control time together by 5; retain actual serialized pins.
    defparam dut.u_core.u_tx.BAUD_DIV=10;
    defparam dut.u_core.u_rx.BAUD_DIV=10;
    defparam dut.u_core.u_debug.rx.TIMEOUT_CLOCKS=50000;
    integer tick_clocks=0;
    always @(negedge clk)begin
        control_tick=0;
        if(tick_clocks==9999)begin tick_clocks=0;control_tick=1;end
        else tick_clocks=tick_clocks+1;
    end
    integer f,scan,n,j,value;
    reg [7:0] byte_rx;
    integer k;
    always @(negedge tx)begin
        #300;
        for(k=0;k<8;k=k+1)begin byte_rx[k]=tx;#200;end
        if(tx!==1'b1)$fatal(1,"UART stop bit invalid");
        $display("RX %02h",byte_rx);
    end
    task send_byte(input [7:0] data);
        integer b;
        begin
            rx=0;#200;
            for(b=0;b<8;b=b+1)begin rx=data[b];#200;end
            rx=1;#200;
        end
    endtask
    initial begin
        // Inject stable measured states; UART command/ack path is not bypassed.
        force dut.alpha_avg=16'd49953;
        force dut.enc_pos=-32'sd2080;
        force dut.u_core.tick=control_tick;
        #100;rst_n=1;#4000000;
        f=$fopen("sim/out/debug_uart_stimulus.txt","r");
        if(f==0)$fatal(1,"Missing UART stimuli");
        while(!$feof(f))begin
            scan=$fscanf(f,"%d",n);
            if(scan==1)begin
                for(j=0;j<n;j=j+1)begin
                    scan=$fscanf(f,"%h",value);send_byte(value[7:0]);
                end
                #500000;
            end
        end
        $fclose(f);#600000;
        $display("tb_debug_uart PASS");$finish;
    end
    initial begin #500000000;$fatal(1,"tb_debug_uart TIMEOUT");end
endmodule
